const fs = require('fs')
const path = require('path')

class SqlGenerator {
  constructor(specPath, outputPath) {
    this.specPath = specPath
    this.outputPath = outputPath
  }

  generateInitSql(schemas, systemConfig) {
    const dbName =
      systemConfig.packageJson?.main?.name?.toLowerCase().replace(/\s+/g, '_') || 'ai_dashboard'
    let sqlContent = `-- AI Native Development Dashboard - Database Initialization Script
-- Generated by Spec as Code Generator

CREATE DATABASE IF NOT EXISTS \`${dbName}\` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE \`${dbName}\`;

SET FOREIGN_KEY_CHECKS = 0;

`

    for (const [schemaName, schema] of Object.entries(schemas)) {
      const tableName = schemaName.replace(/-/g, '_') + 's'
      sqlContent += `-- Table structure for table \`${tableName}\` (${schema.title})\n`
      sqlContent += `DROP TABLE IF EXISTS \`${tableName}\`;\n`
      sqlContent += `CREATE TABLE \`${tableName}\` (\n`
      sqlContent += `  \`id\` INT AUTO_INCREMENT PRIMARY KEY,\n`

      for (const [propKey, propValue] of Object.entries(schema.properties)) {
        const columnName = this.toSnakeCase(propKey)

        // 排除 id, created_at, updated_at，因为我们会手动添加
        if (columnName === 'id' || columnName === 'created_at' || columnName === 'updated_at')
          continue

        const columnType = this.getMysqlType(propValue)
        const nullable = propValue.required ? 'NOT NULL' : 'NULL'
        const defaultValue = this.getDefaultValue(propValue)
        const comment = propValue.description ? ` COMMENT '${propValue.description}'` : ''

        sqlContent += `  \`${columnName}\` ${columnType} ${nullable}${defaultValue}${comment},\n`
      }

      sqlContent += `  \`created_at\` DATETIME DEFAULT CURRENT_TIMESTAMP,\n`
      sqlContent += `  \`updated_at\` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP\n`
      sqlContent += `) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;\n\n`
    }

    sqlContent += `SET FOREIGN_KEY_CHECKS = 1;\n`

    const sqlPath = path.join(this.outputPath, 'init.sql')
    this.ensureDirectoryExists(sqlPath)
    fs.writeFileSync(sqlPath, sqlContent)
    return sqlPath
  }

  getMysqlType(prop) {
    if (prop.format === 'objectId') return 'VARCHAR(64)'
    if (prop.format === 'date-time' || prop.format === 'date') return 'DATETIME'

    switch (prop.type) {
      case 'string':
        if (prop.maxLength > 1000) return 'TEXT'
        return `VARCHAR(${prop.maxLength || 255})`
      case 'integer':
        return 'INT'
      case 'number':
        return 'DECIMAL(10, 2)'
      case 'boolean':
        return 'TINYINT(1)'
      case 'array':
      case 'object':
        return 'JSON'
      case 'date':
        return 'DATETIME'
      default:
        return 'VARCHAR(255)'
    }
  }

  getDefaultValue(prop) {
    if (prop.default === undefined) return ''

    if (typeof prop.default === 'string') {
      return ` DEFAULT '${prop.default}'`
    }
    if (typeof prop.default === 'boolean') {
      return ` DEFAULT ${prop.default ? 1 : 0}`
    }
    return ` DEFAULT ${prop.default}`
  }

  toSnakeCase(str) {
    return str.replace(/[A-Z]/g, (letter) => `_${letter.toLowerCase()}`).replace(/^_/, '')
  }

  ensureDirectoryExists(filePath) {
    const dir = path.dirname(filePath)
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true })
    }
  }
}

module.exports = SqlGenerator
